const notebookUrls = [
  "https://web.runme.dev/?doc=https%3A%2F%2Fdrive.google.com%2Ffile%2Fd%2F1ZxXleLr8obZjsgf8ytAbJ9YM0cI3YSJl%2Fview",
];

const examples = [];
for (const notebookUrl of notebookUrls) {
  const extracted = await trainingExamples.extract(notebookUrl);
  examples.push(...extracted);
}

console.log({ exampleCount: examples.length });
if (examples.length > 0) {
  await trainingExamples.preview(examples);
}

const source = { driveFileId: '1ZxXleLr8obZjsgf8ytAbJ9YM0cI3YSJl' };
const extracted = await trainingExamples.extract({ source, sources: ['named-revision'], syntheticReverse: false });
console.log({ count: extracted.examples.length, issues: extracted.issues, checksum: extracted.sourceChecksum, ruleVersion: extracted.ruleVersion });
if (extracted.issues.length) throw new Error('Review extraction diagnostics before exporting');
if (!extracted.examples.length) throw new Error('Source needs a named revision, explicit cell decision, or commented cell version with a content change');
const rows = [];
for (const example of extracted.examples) {
  const input = await trainingExamples.prepare(example);
  const row = await trainingExamples.encodeSftExample(input, example.accepted);
  if (row.messages.some(m => m.role === 'assistant')) throw new Error('Unexpected assistant target');
  rows.push(row);
}
const jsonl = await trainingExamples.encodeJsonl(rows);
const parsed = jsonl.trimEnd().split('\n').map(line => JSON.parse(line));
if (parsed.length !== rows.length || !jsonl.endsWith('\n')) throw new Error('JSONL framing mismatch');
const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(jsonl));
const sha256 = Array.from(new Uint8Array(digest), b => b.toString(16).padStart(2, '0')).join('');
console.log({ rows: rows.length, bytes: new TextEncoder().encode(jsonl).length, sha256, labels: parsed.map(r => r.reference_answer), uploaded: false });
await trainingExamples.preview(extracted.examples);

// Definitions only: executing this cell does not upload or submit anything.
// Uses the key and endpoint saved in Authentication Settings → OpenAI API.
async function uploadReviewedDataset(jsonl, filename) {
  return await trainingExamples.uploadOpenAIJsonl({ jsonl, filename });
}
async function submitApprovedJob(job) {
  // Supply the complete target-service request after reviewing resource costs.
  return await trainingExamples.submitTrainingJob({ job });
}
console.log('Helpers defined; no upload or training performed.');
